import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>照片里有些部分不该被分享。背景里的一张脸、信封上的地址、屏幕上的密码，一旦落到错误的人手里，都可能造成真实的伤害。</p>\n<p>模糊和打码是遮住这些细节的两种办法。两者都能让一个区域无法辨认，但看起来不同，保护效果也不同。</p>\n<p>这篇指南会讲清两种方法、各自适合什么时候用，以及怎么干净地操作。内容包括画笔模式与整图模式、强度设置，以及那些让敏感细节依然可读的错误。需要遮住点什么时，<a href=\"/zh/mohu-masaike/\">图片模糊与马赛克</a>可以只涂抹敏感区域，也可以整图处理。</p>\n<h2 id=\"what-blur-does\">模糊对图片做了什么</h2>\n<p>模糊是把相邻像素的颜色平均化，让一个区域变柔和。锐利的边缘融化了，文字读不出来了，人脸的特征也消失了。</p>\n<p>轻度模糊只让细节稍微变软，重度模糊会把区域变成一片平滑的色彩。强度设置决定了还剩下多少信息。</p>\n<p>模糊最适合背景和温和的匿名处理。背景轻轻一糊，照片看起来依然自然，观众的注意力自然回到主体上。</p>\n<p>隐藏敏感信息时，模糊必须够重。脸或地址上的轻度模糊有时还能被锐化回来，所以涉及隐私时要用重度模糊。</p>\n<h2 id=\"what-pixelate-does\">打码对图片做了什么</h2>\n<p>打码是把一个区域换成大块的纯色方块，像马赛克一样。每个方块是底下像素的平均颜色，所有精细细节都消失了。</p>\n<p>方块大小决定强度。方块小，还能隐约看出形状；方块大，区域就只剩几块扁平的色块。</p>\n<p>打码看着就是刻意遮挡，这在想让观众知道“这里藏了东西”时很有用。模糊的脸看着像艺术处理，打码的脸看着像审查涂抹。</p>\n<p>隐藏文字时，打码通常比轻度模糊更安全。大方块的马赛克能彻底破坏字母形状，轻柔的模糊有时还会留下一部分可读性。</p>\n<h2 id=\"why-censor-images\">人们为什么要模糊和打码照片</h2>\n<p>隐私是最主要的原因。网上分享的照片可能暴露人脸、地址、车牌和文件，遮住这些细节能保护照片里的人。</p>\n<p>父母在公开分享家庭照片前，会模糊孩子们的脸。孩子并没有同意上网，模糊能让他们远离可搜索的图片。</p>\n<p>记者和研究人员在敏感报道里给人脸打码。匿名受访的线人需要的是身份被隐藏，不只是变柔和。</p>\n<p>企业会模糊截图里的屏幕。仪表盘截图可能暴露客户姓名、内部网址或密码，仔细模糊之后再分享就安全了。</p>\n<h2 id=\"brush-area-mode\">画笔区域模式：涂抹遮盖细节</h2>\n<p>画笔区域模式可以把模糊或打码精确涂到需要的地方。在脸、车牌或一行文字上拖动画笔，只有涂到的地方会被遮盖。</p>\n<p>图片其余部分保持清晰。这种精确度让画笔模式成为大多数隐私工作的正确选择，因为通常只有照片的一小部分需要隐藏。</p>\n<p>画笔大小很重要。大画笔几下就能盖住一张脸，小画笔可以沿着单个词或小细节描，不碰其余部分。</p>\n<p>涂错了就用撤销按钮去掉最后一笔。也可以完全重置画笔重新开始，比费劲修补一笔坏的涂抹更快。</p>\n<h2 id=\"whole-image-mode\">整图模式：全部模糊</h2>\n<p>整图模式把效果一次性应用到整张照片。整张图片都敏感，或者想要一个模糊背景做设计时，就用它。</p>\n<p>完全模糊的照片很适合做文字或演示文稿的背景。颜色和氛围还在，没有任何东西会分散观众对文字的注意力。</p>\n<p>切换到整图模式后，目标区域从画笔涂抹变成整个画面。工具会把当前的模糊或打码强度应用到所有地方。</p>\n<p>隐私用途要慎用整图模式。整张模糊的照片什么都藏住了，但主体也被藏住了，公开分享照片时很少是正确的选择。</p>\n<h2 id=\"smooth-blur-strength\">平滑模糊强度：多强才够</h2>\n<p>模糊强度是一个刻度，合适的值取决于你要藏什么。背景只需要轻度模糊，脸或地址需要重度模糊。</p>\n<p>脸要用重度模糊，彻底去掉所有可辨认的特征。眼睛和微笑还看得见的轻度模糊，保护不了任何人。</p>\n<p>文字同样需要重度模糊。轻微模糊的词有时能从长度和形状猜出来，尤其是上下文已经给出提示的时候。</p>\n<p>放大检查结果。按全尺寸看，文字还能读、脸还能认，就调高强度再检查一次。</p>\n<h2 id=\"mosaic-block-size\">马赛克方块大小：方块越大，遮盖越安全</h2>\n<p>马赛克方块大小和模糊强度的作用一样：方块越大，藏得越多。方块小还保留着区域的大致形状，方块大就只剩几块扁平的色块。</p>\n<p>小截图用中等方块就够了。文字很小，就算是适度的方块也能彻底破坏字母形状。</p>\n<p>大照片用大方块。高分辨率照片里的人脸需要大方块才能藏住特征，小方块还会留下眼睛和嘴巴的轮廓。</p>\n<p>拿不准就选大一点。马赛克稍强一点看着是故意的，稍弱一点却会让敏感细节依然可读。</p>\n<h2 id=\"brush-size-settings\">画笔大小：按细节选工具</h2>\n<p>画笔大小要和你要隐藏的细节匹配。脸需要大画笔，车牌需要中等画笔，单个词需要小画笔。</p>\n<p>画笔太大，遮住的比想遮的多。可能盖住旁边的一张脸，或者图片里本来不需要隐藏的有用部分。</p>\n<p>画笔太小，盖住大面积要涂很多笔，笔触之间的缝隙可能漏出敏感细节的一小条。</p>\n<p>边涂边调整画笔大小。先用大画笔涂主要区域，再换小画笔清理边缘、补上漏掉的地方。</p>\n<h2 id=\"hiding-faces\">正确隐藏人脸</h2>\n<p>藏一张脸需要完全覆盖。眼睛、鼻子、嘴巴和发际线都带有身份信息，所以遮盖区域必须盖住整个头部。</p>\n<p>人脸通常用打码更安全。大方块的马赛克能彻底破坏面部特征，轻度模糊有时还会留下足够认人的信息。</p>\n<p>盖住整个头，不只是眼睛。眼睛上的黑条是电影里的老套路，不是真正的保护，因为脸的其余部分依然可认。</p>\n<p>按全尺寸检查结果。放大看被遮盖的脸，确认没有任何特征可见，再检查背景里的倒影有没有再次露出这张脸。</p>\n<h2 id=\"hiding-text-and-numbers\">隐藏文字、数字与地址</h2>\n<p>文字比脸更难藏，因为哪怕只露出半个字母也可能暴露整个词。车牌、地址或密码需要完全覆盖。</p>\n<p>大方块的打码是隐藏文字最安全的方法。它彻底破坏字母形状，轻柔的模糊有时还会留下文字轮廓可读。</p>\n<p>整行都盖住，不只是敏感的那个词。行的长度和周围的词可能暴露被藏的部分，所以遮盖要慷慨一点。</p>\n<p>检查图片里其他地方有没有同样的文字。信封上的地址可能还出现在背景里的信件上，两处都要遮盖。</p>\n<h2 id=\"hiding-backgrounds\">模糊背景：突出主体，也保护隐私</h2>\n<p>模糊背景能让主体脱颖而出。人像摄影师几十年来一直在用这种效果，数码模糊能在事后达到同样的结果。</p>\n<p>用画笔把模糊涂在背景上，主体保持清晰。清晰主体与柔和背景的对比，能把观众的目光准确引到你想让他们看的地方。</p>\n<p>隐私方面，模糊背景能隐藏地点。街牌、门牌号或可识别的建筑在背景里，可能暴露照片的拍摄地点。</p>\n<p>背景用轻度模糊，敏感细节用重度模糊。两种强度服务于不同的目的，搞混了两者都会变弱。</p>\n<h2 id=\"formats-and-transparency\">格式与透明度</h2>\n<p>工具支持常见的图片格式，包括JPG、PNG、WebP和HEIC，文件最大20MB。导出可选JPG、PNG或WebP，按需要选择。</p>\n<p>导出PNG或WebP能保留底图的透明度。如果来源是透明PNG图片，遮盖后的导出图透明区域依然透明。</p>\n<p>照片通常导出JPG最好。文件小，哪里都能打开，遮盖区域压缩后也很干净。</p>\n<p>JPG和WebP导出时会出现画质滑杆，PNG导出时没有，因为PNG是无损的，没有画质可调。</p>\n<h2 id=\"privacy-local-processing\">隐私：不上传也能打码</h2>\n<p>所有模糊和打码都在浏览器里完成。照片不会上传到服务器，这对包含人脸、证件或私人地址的图片来说很重要。</p>\n<p>这是打码工具最重要的特性。需要隐藏的照片，永远不该为了模糊一张脸就发到看不见的服务器上。</p>\n<p>工具导出时还会清除EXIF GPS数据。下载下来的遮盖后照片不再带有拍摄地点的记录，这是第二层保护。</p>\n<p>没有遮盖的原文件要保管好、单独存放。分享遮盖版本之后，原文件是唯一还能看到完整图片的副本。</p>\n<h2 id=\"common-mistakes\">打码时最容易犯的错</h2>\n<p>最常见的错误是遮盖太轻。脸上的轻柔模糊或文字上的小马赛克，可能还会留下细节可读，整个遮盖就白做了。</p>\n<p>另一个错误是漏掉倒影。同一张照片里，脸可能出现在镜子、窗户或太阳镜里，每一处都要遮盖。</p>\n<p>很多人还会忘记元数据。脸模糊了的照片，可能还带有暴露拍摄地点的GPS坐标，导出设置要检查。</p>\n<p>最后，不要不小心分享了原文件。遮盖图和原文件常常并排放在下载文件夹里，附错了附件，之前的工作就全白费了。</p>\n<h2 id=\"censoring-workflow\">安全分享的工作流程</h2>\n<p>打开原照片，列出所有需要隐藏的东西：人脸、地址、车牌、屏幕、文件。背景和前景都要检查。</p>\n<p>用画笔逐个涂掉，文字用打码，脸用重度模糊或马赛克。每涂一笔都放大确认完全覆盖。</p>\n<p>导出遮盖版本，按全尺寸检查。找漏掉的倒影、可读的文字，以及第一遍忽略的细节。</p>\n<p>只分享遮盖后的文件。原文件放在单独的文件夹里，永远不要和遮盖版本附在同一条消息或帖子里。</p>\n<h2 id=\"blurring-for-video-thumbnails\">视频封面与封面图的模糊处理</h2>\n<p>模糊的照片很适合做视频封面的背景。柔和的色彩定下氛围，顶上的标题文字保持锐利、易读。</p>\n<p>封面用整图模式加适度模糊。图片要能认出是个场景，又要够柔和，文字才能在画面里占主导。</p>\n<p>模糊里让主体隐约可见。纯色的封面感觉空洞，文字后面隐约有个主体，感觉就是特意的。</p>\n<p>封面导出用高画质JPG。文件在小尺寸下也要看着干净，低画质导出会连标题文字一起变软。</p>\n<p>分步骤的操作见<a href=\"/zh/blog/ruhe-mohu-dama-tupian/\">如何模糊或打码图片</a>。对比分析读<a href=\"/zh/blog/mohu-vs-masaike-duibi/\">模糊 vs 马赛克：隐藏人脸、文字与细节</a>；想彻底删除位置数据，用<a href=\"/zh/shanchu-tupian-yuanshuju/\">删除图片元数据工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"模糊的人脸以后还能恢复吗？","answer":"下载好的文件里不能恢复，前提是模糊够重。模糊是把像素平均化，破坏了原始细节，没什么可恢复的。很轻的模糊有时能被锐化回来，所以人脸需要重度模糊或大方块马赛克。"},{"question":"隐藏车牌时，打码比模糊更安全吗？","answer":"通常是的。大方块的马赛克能彻底破坏字母和数字的形状，轻柔的模糊有时还会留下轮廓可读。文字和数字用打码，人脸用重度模糊或马赛克。"},{"question":"手机上怎么模糊照片里的人脸？","answer":"在手机浏览器里打开模糊与马赛克工具，上传照片，选画笔区域模式。手指涂抹人脸，用大画笔加高强度模糊或马赛克，预览后下载结果。"},{"question":"人像照的整个背景都应该模糊吗？","answer":"只有背景暴露了隐私时才需要，比如街牌或门牌号。轻度模糊也能让主体更突出，这属于创意选择。隐私用重度模糊，突出主体用轻度模糊。"},{"question":"涂抹时漏掉一小块怎么办？","answer":"用撤销按钮去掉最后一笔，或者换小画笔补涂漏掉的区域。每涂一笔都放大检查缝隙。想重新开始时，重置按钮能清除所有画笔涂抹。"},{"question":"模糊照片会清除位置信息吗？","answer":"会。用工具导出时，文件里的EXIF GPS标签会被清除。模糊藏住了看得见的细节，导出清掉了隐藏的位置记录。想保留这些数据的话，留好原文件。"}];
